sales = [("서울", 120), ("부산", 85), ("대구", 64), ("서울", 40)]

totals = {}
for city, amount in sales:
    totals[city] = totals.get(city, 0) + amount

ranking = sorted(totals.items(), key=lambda row: row[1], reverse=True)
f"합계: {totals}\n1위: {ranking[0][0]} ({ranking[0][1]:,}만원)"

