expense-syntax-together.code:
column_map = {"조직": "부서", "사용금액": "금액"}
records = [
    {"조직": "영업팀", "사용금액": 50000},
    {"조직": "관리팀", "사용금액": 120000},
    {"조직": "영업팀", "사용금액": 80000},
]
amount_limit = 100000

def classify_expense(amount, limit):
    if amount >= limit:
        return "확인필요"
    return "정상"

results = []
total = 0
flagged_count = 0

for record in records:
    amount = record["사용금액"]
    label = classify_expense(amount, amount_limit)
    results.append({
        column_map["조직"]: record["조직"],
        column_map["사용금액"]: amount,
        "결과": label,
    })
    total = total + amount
    if label == "확인필요":
        flagged_count = flagged_count + 1

print(f"합계 {total:,}원")
print(f"확인필요 {flagged_count}건")
for result in results:
    print(f"{result['부서']}: {result['금액']:,}원, {result['결과']}")
